const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={gym:'M5 8v8m4-11v14m6-14v14m4-11v8M9 12h6',home:'M3 11l9-8 9 8M5 10v11h14V10M9 21v-7h6v7',food:'M5 3v7m4-7v7M3 7h8M7 10v11M17 3v18m0-18c5 4 5 10 0 10',coach:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',quest:'M8 3h8v8a4 4 0 01-8 0V3M8 5H4v4a4 4 0 004 4m8-8h4v4a4 4 0 01-4 4M12 15v5m-4 1h8',settings:'M12 8a4 4 0 100 8 4 4 0 000-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10l2 2M5 19l2-2M17 7l2-2',moon:'M20 15a8 8 0 01-11-11 9 9 0 1011 11',check:'M5 12l4 4L19 6',plus:'M12 5v14M5 12h14',sync:'M4 8a8 8 0 0114-3l3 3m0-5v5h-5M20 16a8 8 0 01-14 3l-3-3m0 5v-5h5',clock:'M12 8v5l3 2M21 12a9 9 0 11-18 0 9 9 0 0118 0',water:'M12 3c-3 5-7 9-7 13a7 7 0 0014 0c0-4-4-8-7-13',arrow:'M5 12h14m-5-5l5 5-5 5',close:'M6 6l12 12M6 18L18 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.gym}"/></svg>`;
const uuid=()=>crypto.randomUUID();
const date=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const pretty=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});
let state={records:[],messages:[],config:{},user:null,profile:null},view=location.hash.slice(1)||'overview',sample=false,currentExercise=0,busy=false,restUntil=0,restPause=0,toastTimer;
const nav=[['overview','home','Daily Overview'],['workouts','gym','Workouts'],['nutrition','food','Nutrition'],['coach','coach','AI Coach'],['quests','quest','Seasons & Quests']];
const records=k=>state.records.filter(r=>r.kind===k);
const active=()=>records('workout').find(r=>r.value.status==='active');
const meals=()=>records('meal').filter(r=>r.value.date===selectedDate);
let selectedDate=date();
const totals=()=>meals().reduce((a,r)=>{for(const k of ['calories','protein','carbs','fat'])a[k]+=r.value[k];return a;},{calories:0,protein:0,carbs:0,fat:0});
const recovery=()=>records('recovery').find(r=>r.value.date===selectedDate);
function toast(message,undo){clearTimeout(toastTimer);$('#toast').innerHTML=`${esc(message)}${undo?'<button id="undo">Undo</button>':''}`;$('#toast').classList.add('visible');if(undo)$('#undo').onclick=()=>run(undo);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?15000:6000);}
async function api(path,method='GET',data){if(path==='/api/coach')return {answer:'You’re building a solid rhythm. Keep your next session focused on controlled reps and leave room for recovery.',observations:['Your journal includes training, nutrition, and recovery.'],suggestions:['Finish the planned sets at a comfortable effort.','Keep logging meals to see your daily pattern.'],limitations:'Illustrative coaching response for this prototype.'};if(method==='DELETE'){state.records=state.records.filter(r=>r.id!==path.split('/').at(-1));return {};}if(path==='/api/profile')return data;if(path==='/api/sheets/sync'){state.integration={sheet_id:'prototype',last_sync:Date.now()};return {};}return {};}
async function load(){state={records:[],messages:[],config:{google:true,ai:true},user:null,profile:null};view='landing';render();}
async function save(kind,value,record){let result;if(sample)result={id:record?.id||uuid(),kind,value,version:(record?.version||0)+1,updated:Date.now()};else result=await api(record?`/api/records/${record.id}`:'/api/records',record?'PUT':'POST',{kind,value,version:record?.version});state.records=state.records.filter(r=>r.id!==result.id);state.records.unshift(result);return result;}
async function remove(record){if(!sample)await api(`/api/records/${record.id}`,'DELETE',{version:record.version});state.records=state.records.filter(r=>r.id!==record.id);render();toast('Entry deleted.',async()=>{await save(record.kind,record.value);render();toast('Entry restored.');});}
async function run(fn){if(busy)return;busy=true;document.body.classList.add('is-busy');const submits=[...document.querySelectorAll('button[type=submit]')].map(b=>[b,b.disabled]);submits.forEach(([b])=>b.disabled=true);try{await fn();}catch(e){const err=$('#modal .form-error');if(err)err.textContent=e.message;toast(e.message);}finally{busy=false;document.body.classList.remove('is-busy');submits.forEach(([b,disabled])=>{if(b.isConnected)b.disabled=disabled;});}}
function brand(){const content=`<span class="brand-mark">${icon('gym')}</span><span>OpenGym<small>Your training journal</small></span>`;return state.user||sample?`<a class="brand" href="#overview" data-view="overview" aria-label="OpenGym home">${content}</a>`:`<div class="brand">${content}</div>`;}
const cast=[{name:'Sage',role:'The All-Rounder',trait:'Curious · Adaptable',specialty:'Balanced habits',line:'A little of everything. A little more you.',quest:'A week of movement, nourishment, and recovery.'},{name:'Atlas',role:'The Builder',trait:'Steady · Determined',specialty:'Strength training',line:'Small reps. Lasting strength.',quest:'Complete three focused strength sessions.'},{name:'Nova',role:'The Acrobat',trait:'Playful · Precise',specialty:'Calisthenics & mobility',line:'Find what your body can do.',quest:'Explore a bodyweight skill and daily mobility.'},{name:'Dash',role:'The Runner',trait:'Energetic · Adventurous',specialty:'Endurance',line:'The next adventure starts with one step.',quest:'Build a comfortable rhythm with three runs.'},{name:'Cleo',role:'The Nourisher',trait:'Thoughtful · Inventive',specialty:'Nutrition',line:'Make feeling good part of your day.',quest:'Keep a nourishing meal journal for five days.'},{name:'Luna',role:'The Restorer',trait:'Calm · Reassuring',specialty:'Sleep & recovery',line:'Rest is how you come back stronger.',quest:'Create a wind-down routine for five evenings.'}];
let characterIndex=0;
const accentOptions=[['peach','Peach','#ffb98b'],['sage','Sage','#b9cfad'],['lavender','Lavender','#c9b9e5'],['sky','Sky','#acd0e1'],['rose','Rose','#e6b6c4']];
function applyAccent(){const key=localStorage.getItem('og-accent')||'peach';document.body.dataset.accent=accentOptions.some(a=>a[0]===key)?key:'peach';}
const companionNotes=[['Exercise mat','A reminder to make room for movement, nourishment and recovery. Sage suits a balanced approach.'],['Dumbbell','A reminder to build strength patiently. Atlas suits a focus on consistent training.'],['Gymnastics rings','A reminder to explore control and mobility. Nova suits bodyweight skills and playful practice.'],['Running watch','A reminder to find your own pace. Dash suits endurance and a steady movement rhythm.'],['Nourishing bowl','A reminder that food supports your day. Cleo suits mindful meals and nutrition habits.'],['Recovery pillow','A reminder that rest counts too. Luna suits sleep routines and recovery.']];
const accessoryPaths=['M7 5h10v14H7z M7 6c0-3 10-3 10 0s-10 3-10 0 M7 9h10','M3 8v8m3-10v12m12-12v12m3-10v8M6 12h12','M7 2v7m10-7v7M7 9a5 5 0 100 10 5 5 0 000-10M17 9a5 5 0 100 10 5 5 0 000-10','M8 2h8v5M8 17v5h8v-5M6 7h12v10H6zM12 9v3l2 1','M3 11h18c-1 7-4 10-9 10S4 18 3 11M7 8l2-4m4 4V3m4 5 2-3','M4 5q8 3 16 0v14q-8-3-16 0V5z'];
function companionCard(){const c=cast[characterIndex],n=companionNotes[characterIndex];return '<button class="avatar-studio game-avatar companion-card" data-action="companion-flip" aria-label="Learn about '+c.name+'" aria-expanded="false"><span class="companion-flipper"><span class="companion-front"><span class="cast-stage" data-mode="dashboard" data-character="'+characterIndex+'"></span><span class="companion-hint">Meet '+c.name+' ↻</span></span><span class="companion-back" aria-hidden="true"><svg class="persona-accessory" viewBox="0 0 24 24" aria-hidden="true"><path d="'+accessoryPaths[characterIndex]+'"/></svg><strong>'+n[0]+'</strong><span>'+n[1]+'</span><small>Your companion suggests a focus; every habit stays available.</small><span class="companion-hint">Back to '+c.name+' ↻</span></span></span></button>';}

let doorwayArrival=false;let doorwayTimer;
function doorway(){return '<div class="world-door" aria-hidden="true"><div class="door-leaf door-left"></div><div class="door-leaf door-right"></div><div class="door-caption"><span class="eyebrow">A LITTLE COMPANY. A NEW CHAPTER.</span><strong>A little space<br>for you.</strong><span>Your next chapter starts here.</span></div></div>';}
function welcome(){return `<main class="cast-welcome">${brand()}<div class="cast-login-layout"><section class="cast-world"><span class="eyebrow">SIX PERSONALITIES. YOUR OWN PATH.</span><h1>Your journey.<br><em>Your kind of hero.</em></h1><div class="cast-stage entrance-stage" data-mode="login" data-character="0">${doorway()}</div><p>Meet your companions. A little movement, a little nourishment,<br>and a world of possibility.</p><div class="cast-name-strip">${cast.map(c=>`<span>${c.name}</span>`).join('')}</div></section><section class="cast-login-panel"><span class="eyebrow">WELCOME TO OPENGYM</span><h2>Make room<br>for <em>yourself.</em></h2><p>Your training, your habits, your own pace.<br>Choose the companion who feels like you.</p><button class="signin wide" data-action="google-preview"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="#4285f4" d="M22 12.2c0-.7-.1-1.4-.2-2.1H12v4h5.6a4.8 4.8 0 01-2.1 3.2v2.6h3.4c2-1.8 3.1-4.4 3.1-7.7Z"/><path fill="#34a853" d="M12 22c2.8 0 5.2-.9 6.9-2.5l-3.4-2.6c-.9.6-2.1.9-3.5.9-2.7 0-5-1.8-5.8-4.2H2.7v2.7A10.4 10.4 0 0012 22Z"/><path fill="#fbbc05" d="M6.2 13.6a6.3 6.3 0 010-3.2V7.7H2.7a10.3 10.3 0 000 8.6Z"/><path fill="#ea4335" d="M12 6.2c1.5 0 2.8.5 3.8 1.5l2.9-2.9A10.1 10.1 0 0012 2a10.4 10.4 0 00-9.3 5.7l3.5 2.7C7 8 9.3 6.2 12 6.2Z"/></svg>Continue with Google</button><span class="login-next">Sign in → Meet your character → Begin your journey</span><div class="prototype-note">Interactive prototype · Google sign-in is simulated</div></section></div></main>`;}
function characterSelection(){const c=cast[characterIndex];return `<main class="character-screen ${doorwayArrival?'door-arrival':''}"><header class="character-header">${brand()}<span class="badge">01 / CHOOSE YOUR COMPANION</span><button class="quiet" data-action="prototype-logout">Sign out</button></header><div class="selection-heading"><span class="eyebrow">A CHARACTER. A LITTLE COMPANY.</span><h1>Who’s joining <em>your journey?</em></h1><p>Different personalities. The same belief: progress happens at your pace.</p></div><div class="cast-stage ${doorwayArrival?'reveal-stage':''}" data-reveal="${doorwayArrival?'1':'0'}" data-mode="selection" data-character="${characterIndex}">${doorwayArrival?doorway():''}</div><div class="character-controls"><button class="quiet" data-character-step="-1" aria-label="Previous character">←</button><span>Swipe, scroll, or choose a character</span><button class="quiet" data-character-step="1" aria-label="Next character">→</button></div><div class="character-lineup" aria-label="Character lineup">${cast.map((c,i)=>`<button data-character-choice="${i}" aria-pressed="${i===characterIndex}" class="${i===characterIndex?'chosen':''}"><span class="character-dot dot-${i}"></span><strong>${c.name}</strong><small>${c.role}</small></button>`).join('')}</div><section class="character-details"><div><span class="eyebrow">${c.trait}</span><h2>${c.name}<small>${c.role}</small></h2><p>“${c.line}”</p></div><div class="character-specialty"><span class="eyebrow">SPECIALTY · ${c.specialty}</span><p>${c.quest}</p><span class="character-footnote">A suggested path. Every companion can explore every habit.</span></div><button class="primary" data-action="choose-character">Choose ${c.name} as my companion ${icon('arrow')}</button></section></main>`;}
function selectCharacter(i){characterIndex=(i+cast.length)%cast.length;render();const line=document.querySelector('.character-lineup'),el=line?.querySelector('.chosen');if(el)line.scrollTo({left:el.offsetLeft-line.offsetLeft-(line.clientWidth-el.clientWidth)/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function avatarArt(id=state.user?.id||'alex',override){const preset=override??Number(localStorage.getItem('og-avatar-'+id)??(id==='maya'?1:id==='sam'?2:0)),skin=['#ce936b','#945d45','#e8b28a'][preset],hair=['#34302f','#2c2025','#674534'][preset],shirt=['#b7ccad','#b9abe0','#9dbecf'][preset];return `<svg class="companion-art" viewBox="0 0 360 320" role="img" aria-label="Your personal OpenGym avatar"><defs><radialGradient id="skin-${id}-${preset}" cx=".3" cy=".2"><stop stop-color="${skin}"/><stop offset="1" stop-color="${skin}" stop-opacity=".85"/></radialGradient><linearGradient id="shirt-${id}-${preset}" x2=".8" y2="1"><stop stop-color="${shirt}"/><stop offset="1" stop-color="${shirt}" stop-opacity=".65"/></linearGradient></defs><ellipse cx="180" cy="282" rx="94" ry="12" fill="#6a3b2517"/><path d="M94 267c3-68 39-89 86-89s83 21 86 89q-86 35-172 0" fill="url(#shirt-${id}-${preset})"/><path d="M143 205q37 35 74 0l-15-30h-44Z" fill="${skin}"/><ellipse cx="180" cy="118" rx="64" ry="77" fill="${hair}"/><circle cx="121" cy="140" r="13" fill="${skin}"/><circle cx="239" cy="140" r="13" fill="${skin}"/><path d="M124 107q0-55 56-55t56 55v38q-4 57-56 63-52-6-56-63Z" fill="url(#skin-${id}-${preset})"/><path d="M118 114q-7-76 62-76 69 0 64 76l-17-23q-33-3-61-26-11 36-48 49" fill="${hair}"/><path d="M140 124q10-7 20-1m40 0q10-6 20 1" fill="none" stroke="${hair}" stroke-width="4" stroke-linecap="round"/><ellipse cx="153" cy="138" rx="4" ry="6" fill="#302827"/><ellipse cx="207" cy="138" rx="4" ry="6" fill="#302827"/><path d="M180 141l-5 18h10m-23 14q18 16 36 0" fill="none" stroke="#754637" stroke-width="3" stroke-linecap="round"/><ellipse cx="145" cy="158" rx="10" ry="5" fill="#e2817370"/><ellipse cx="215" cy="158" rx="10" ry="5" fill="#e2817370"/><path d="M144 216l7 47m65-47-7 47" stroke="#fff8" stroke-width="3" stroke-linecap="round"/><circle cx="250" cy="74" r="21" fill="#fff8"/><path d="M241 74l6 6 12-13" fill="none" stroke="#557345" stroke-width="4" stroke-linecap="round"/></svg>`;}
function signInPreview(id){sampleJournal();state.user={id};state.config={google:true,ai:true};state.profile.name={alex:'Alex Morgan',maya:'Maya Chen',sam:'Sam Rivera'}[id];sample=true;const saved=localStorage.getItem('og-companion-'+id);characterIndex=saved===null?0:Number(saved);doorwayArrival=saved===null;view=saved===null?'character':'overview';location.hash=view;closeModal();render();doorwayArrival=false;window.scrollTo(0,0);clearTimeout(doorwayTimer);doorwayTimer=setTimeout(()=>{const stage=document.querySelector('.reveal-stage');if(stage){stage.dataset.reveal='0';stage.querySelector('.world-door')?.remove();stage.classList.remove('reveal-stage');document.querySelector('.door-arrival')?.classList.remove('door-arrival');}},matchMedia('(prefers-reduced-motion: reduce)').matches?0:1200);}
function header(){return `<header class="workspace-header">${brand()}<button class="account-entry" data-view="settings" aria-label="Account and settings"><span class="avatar">${esc((state.profile?.name||'O')[0])}</span><span>${esc(state.profile.name.split(' ')[0])}<small>Account & settings</small></span>${icon('arrow')}</button></header>`;}
function sidebar(){const labels={overview:'Today',workouts:'Train',nutrition:'Fuel',coach:'Coach',quests:'Grow'};return `<nav class="journey-dock" aria-label="Main navigation">${nav.map(([id,i,label])=>`<button data-view="${id}" aria-label="${label}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${labels[id]}</span></button>`).join('')}</nav>`;}
function dailyPulse(){const days=Array.from({length:7},(_,i)=>{const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()-6+i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return {key,label:d.toLocaleDateString(undefined,{weekday:'short'}),count:state.records.filter(r=>['workout','meal','recovery'].includes(r.kind)&&r.value.date===key).length};}),logged=days.filter(d=>d.count).length,t=totals(),a=active(),sets=a?.value.exercises.flatMap(e=>e.sets)||[];return `<section class="daily-pulse"><div class="pulse-content"><div class="pulse-top"><span class="eyebrow">YOUR DAILY PULSE</span><button type="button" id="journal-date" class="journal-date-trigger" data-date-picker="open" aria-haspopup="dialog" aria-label="Choose journal date, ${esc(pretty(selectedDate))}">${icon("calendar")}<span>${new Date(selectedDate+"T12:00:00").toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"})}</span></button></div><h2>A little effort.<br><em>A lasting change.</em></h2><p>${logged?`You’ve made space for yourself on ${logged} of the last 7 days.`:'Your first entry is the beginning of a new rhythm.'} Every entry counts.</p><div class="pulse-stats"><div><strong>${logged}<small> / 7</small></strong><span>days with journal entries</span></div><div><strong>${Math.round(t.protein)}<small> / ${state.profile.protein}g</small></strong><span>protein logged ${selectedDate===date()?"today":"on this date"}</span></div><div><strong>${sets.filter(x=>x.done).length}<small> / ${sets.length}</small></strong><span>${a?'sets in your active session':'no active workout'}</span></div></div></div><div class="pulse-art">${companionCard()}<span class="strength-caption">${cast[characterIndex].name} · ${cast[characterIndex].role}</span><div class="rhythm-week" aria-label="Journal activity for the last seven days">${days.map(d=>`<div title="${d.key}: ${d.count} entries"><span class="rhythm-dot ${d.count?'logged':''}">${d.count?icon('check'):''}</span><small>${d.label}</small></div>`).join('')}</div><span class="rhythm-caption">Your rhythm · last 7 days</span></div></section>`;}
function render(){applyAccent();document.body.classList.toggle('light',localStorage.getItem('og-theme')!=='dark');document.body.classList.toggle('cast-flow',view==='character'||view==='landing'||(!state.user&&!sample));document.body.classList.toggle('pulse-page',view==='overview'&&Boolean(state.user||sample));if(view==='character'&&(state.user||sample)){$('#app').innerHTML=characterSelection();return;}if(view==='landing'||(!state.user&&!sample)){$('#app').innerHTML=welcome();return;}if(!['overview','workouts','nutrition','coach','quests','settings'].includes(view))view='overview';$('#app').innerHTML=`<div class="prototype-banner">OpenGym · Interactive prototype <button data-action="switch-user">Switch persona</button></div><div class="shell">${sidebar()}<main class="main" data-current-view="${view}">${header()}${({overview:overview,workouts:workouts,nutrition:nutrition,coach:coachView,quests:quests,settings:settings}[view])()}</main></div>`;updateClock();}
function nutritionSummary(){const t=totals(),p=state.profile;return `<span class="eyebrow">Daily nutrition</span><div class="metric">${Math.round(t.calories).toLocaleString()} <small>/ ${p.calories.toLocaleString()} kcal</small></div><progress value="${t.calories}" max="${p.calories}" aria-label="Calorie goal"></progress><div class="detail-line"><span>${t.calories>p.calories?'Above goal':'Remaining'}</span><strong>${Math.abs(Math.round(p.calories-t.calories))} kcal</strong></div><div class="macro">${[['protein','Protein','cyan'],['carbs','Carbs','green'],['fat','Fat','amber']].map(([k,label,c])=>`<div><small>${label}</small><strong>${Math.round(t[k])} <small>/ ${p[k]}g</small></strong><progress class="${c}" value="${t[k]}" max="${p[k]}" aria-label="${label} goal"></progress></div>`).join('')}</div>`;}
function calorieRing(){const t=totals(),goal=state.profile.calories||2500,p=Math.min(1,t.calories/goal);return `<div class="calorie-orbit"><svg viewBox="0 0 160 160" role="img" aria-label="${Math.round(p*100)} percent of calorie target"><circle class="orbit-track" cx="80" cy="80" r="65"/><circle class="orbit-value" cx="80" cy="80" r="65" pathLength="100" stroke-dasharray="100" stroke-dashoffset="${100-p*100}"/></svg><div><span class="orbit-number">${Math.max(0,goal-t.calories).toLocaleString()}</span><small>kcal remaining</small></div></div>`;}
function activityCalendar(){const end=new Date(selectedDate+'T12:00:00'),days=Array.from({length:35},(_,i)=>{const d=new Date(end);d.setDate(d.getDate()-34+i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');const count=state.records.filter(r=>['meal','workout','recovery'].includes(r.kind)&&r.value.date===key).length;return {key,count,label:d.toLocaleDateString(undefined,{month:'short',day:'numeric'})};});let streak=0;const todayCount=days.at(-1).count;const loggedDates=new Set(state.records.filter(r=>['meal','workout','recovery'].includes(r.kind)).map(r=>r.value.date)),cursor=new Date(end);if(!todayCount)cursor.setDate(cursor.getDate()-1);while(loggedDates.has(cursor.getFullYear()+'-'+String(cursor.getMonth()+1).padStart(2,'0')+'-'+String(cursor.getDate()).padStart(2,'0'))){streak++;cursor.setDate(cursor.getDate()-1);}return `<section class="activity-calendar"><div><span class="eyebrow">CONSISTENCY, AT YOUR PACE</span><h3>Your days add up.</h3><p><strong>${days.filter(d=>d.count).length}</strong> active days in the last 35 · ${streak} day${streak===1?'':'s'} in your journal streak</p><small>Any workout, food, or recovery entry counts. Rest is part of the rhythm.</small></div><div class="calendar-panel"><div class="calendar-blocks" aria-label="Journal activity over the last 35 days">${days.map(d=>`<button type="button" data-calendar-date="${d.key}" class="calendar-day level-${Math.min(3,d.count)}" aria-label="${esc(d.label)}: ${d.count} journal entries" title="${d.label} · ${d.count} entries"></button>`).join('')}</div><div class="calendar-legend"><span>${days[0].label} — ${days.at(-1).label}</span><span>Less <i class="level-0"></i><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i> More</span></div></div></section>`;}
function overview(){const a=active(),r=recovery()?.value;const history=state.records.filter(r=>['workout','meal','recovery'].includes(r.kind)).slice(0,6);return `${dailyPulse()}<div class="journal-sheet"><div class="logger">${icon('plus')}<input id="quick-note" placeholder="What would you like to log?" aria-label="Quick log description"><button class="primary" data-action="quick-log">Log entry</button></div><div class="grid three overview-cards"><section class="card training-card"><div class="card-top"><span class="eyebrow">${a?'Workout in progress':'Scheduled training'}</span><span class="badge">${a?'ACTIVE':'READY WHEN YOU ARE'}</span></div><h3>${esc(a?.value.name||'Your next session')}</h3><p class="subtle">${a?`${a.value.exercises.length} exercises · ${a.value.exercises.flatMap(e=>e.sets).filter(s=>s.done).length} sets logged`:'Choose a template or build your own workout.'}</p><button class="primary wide" data-action="start">${a?'Resume Workout':'Start Workout'}</button><div class="detail-line"><span>This week</span><strong>${completedThisWeek()} workouts completed</strong></div></section><section class="card nutrition-card">${calorieRing()}${nutritionSummary()}<div class="detail-line"><span>${meals().length} foods logged</span><button class="quiet" data-view="nutrition">Details</button></div></section><section class="card recovery-card"><div class="card-top"><span class="eyebrow">Habits & recovery</span><button class="quiet" data-action="recovery">Check in</button></div><div class="detail-line"><span>Sleep</span><strong>${r?`${r.sleep} hours`:'Not logged'}</strong></div><div class="detail-line"><span>Water</span><strong>${r?`${r.water} litres`:'Not logged'}</strong></div><div class="detail-line"><span>Energy</span><strong>${r?`${r.energy} / 5`:'Not logged'}</strong></div><p class="subtle">A quick check-in gives your coach more context.</p></section></div><div class="section-title"><h3>Recent Activity</h3><button class="quiet" data-action="meal">+ Add Food</button></div><section class="card">${history.length?history.map(r=>`<div class="activity-row"><span class="item-icon">${icon(r.kind==='meal'?'food':r.kind==='recovery'?'moon':'gym')}</span><div class="item-copy"><strong>${esc(r.value.name||'Recovery check-in')}</strong><small>${esc(r.value.date)} · ${r.kind==='meal'?`${r.value.calories} kcal · ${r.value.protein}g protein`:r.kind==='workout'?`${r.value.exercises.length} exercises · ${r.value.status}`:`${r.value.sleep}h sleep · ${r.value.water}L water`}</small></div><span class="badge">${r.kind==='workout'&&r.value.status==='completed'?'COMPLETED':r.kind.toUpperCase()}</span></div>`).join(''):'<div class="empty">Your journal starts here.<br>Log a workout, a meal, or your first recovery check-in.</div>'}</section></div>`;}
function completedThisWeek(){const start=new Date();start.setDate(start.getDate()-7);return records('workout').filter(r=>r.value.status==='completed'&&new Date(r.value.date)>=start).length;}
function workouts(){const a=active(),history=records('workout').filter(r=>r.value.status==='completed');if(!a)return `<div class="page-heading"><div><span class="eyebrow">Training journal</span><h2>Make every set count.</h2></div><button class="primary" data-action="start">Start Workout</button></div><section class="card"><div class="empty">${icon('gym')}<br>No workout in progress.<br>Start with a template, then adjust it to your routine.<br><button class="primary" data-action="start">Choose a workout</button></div></section>${workoutHistory(history)}`;
 const w=a.value;currentExercise=Math.min(currentExercise,w.exercises.length-1);const e=w.exercises[currentExercise],all=w.exercises.flatMap(x=>x.sets),done=all.filter(x=>x.done).length;const prev=history.flatMap(r=>r.value.exercises.filter(x=>x.name.toLowerCase()===e.name.toLowerCase()).map(x=>({e:x,unit:r.value.unit}))).find(x=>x.unit===w.unit);const volume=all.filter(s=>s.done).reduce((a,s)=>a+s.weight*s.reps,0);
 return `<div class="page-heading"><div><span class="eyebrow">${esc(w.name)}</span><h2>In session</h2></div><button class="quiet" data-action="finish">Finish Workout</button></div><div class="grid two"><div><section class="card"><div class="exercise-heading"><div><span class="eyebrow">Exercise ${currentExercise+1} of ${w.exercises.length}</span><h2>${esc(e.name)}</h2></div><span class="badge">${e.sets.length} sets · Rest ${e.rest}s</span></div><div class="table-wrap"><table><thead><tr><th>Set</th><th>Previous</th><th>Weight (${w.unit})</th><th>Reps</th><th>RPE</th><th>Status</th></tr></thead><tbody>${e.sets.map((s,i)=>`<tr class="${s.done?'done-row':''}"><td>${i+1}</td><td>${prev?.e.sets[i]?`${prev.e.sets[i].weight} × ${prev.e.sets[i].reps}`:'—'}</td><td><input aria-label="Set ${i+1} weight in ${w.unit}" type="number" min="0" max="1500" step="0.5" value="${s.weight}" data-set="${s.id}" data-field="weight"></td><td><input aria-label="Set ${i+1} reps" type="number" min="0" max="200" value="${s.reps}" data-set="${s.id}" data-field="reps"></td><td><input aria-label="Set ${i+1} RPE" type="number" min="1" max="10" step="0.5" value="${s.rpe??''}" placeholder="—" data-set="${s.id}" data-field="rpe"></td><td><button class="complete ${s.done?'quiet':'primary'}" data-complete="${s.id}" aria-label="${s.done?'Reopen':'Complete'} set ${i+1}">${s.done?icon('check'):'Log'}</button></td></tr>`).join('')}</tbody></table></div><div class="button-row section-title"><button class="quiet" data-action="add-set">+ Add Set</button><button class="quiet" data-action="save-workout">Save Changes</button></div></section><section class="card rest"><div><span class="eyebrow">Rest period</span><div class="clock" id="rest-clock">Ready</div></div><div class="button-row"><button data-action="pause-rest" id="pause-rest">Pause</button><button data-action="extend-rest">+30s</button><button data-action="skip-rest">Skip</button></div></section><div class="section-title"><h3>Exercises in this session</h3><button class="quiet" data-action="add-exercise">+ Add Exercise</button></div>${w.exercises.map((x,i)=>`<div class="upcoming"><button data-exercise="${i}"><strong>${esc(x.name)}</strong><small>${x.sets.filter(s=>s.done).length} / ${x.sets.length} sets complete</small></button>${i===currentExercise?'<span class="badge">CURRENT</span>':icon('gym')}</div>`).join('')}</div><aside class="stack"><section class="card"><h3>Movement History</h3><div class="note"><span class="eyebrow">Last logged session</span><strong>${prev?`${prev.e.sets[0]?.weight} ${w.unit} × ${prev.e.sets[0]?.reps} reps`:'No previous session'}</strong><span class="subtle">Your recorded performance for this exercise.</span></div></section><section class="card"><h3>Plate Calculator</h3><label class="field">Total weight (${w.unit})<input id="plate-total" type="number" value="${w.unit==='kg'?60:135}" min="0"></label><label class="field">Bar weight (${w.unit})<input id="plate-bar" type="number" value="${w.unit==='kg'?20:45}" min="0"></label><button class="wide quiet" data-action="plates">Calculate</button><div id="plate-result" class="plate-result"></div></section><section class="card"><h3>Session Progress</h3><div class="detail-line"><span>Sets logged</span><strong>${done} / ${all.length}</strong></div><progress value="${done}" max="${all.length}" aria-label="Workout progress"></progress><div class="detail-line"><span>Completed volume</span><strong>${volume.toLocaleString()} ${w.unit}</strong></div><p class="subtle">Logged sets save to your account. Save Changes stores edits to planned sets.</p></section></aside></div>`;
}
function workoutHistory(history){return `<div class="section-title"><h3>Workout History</h3></div><section class="card">${history.length?history.slice(0,15).map(r=>`<div class="history-item"><div class="item-copy"><strong>${esc(r.value.name)}</strong><small>${r.value.date} · ${r.value.exercises.flatMap(e=>e.sets).filter(s=>s.done).length} sets</small></div><button class="quiet" data-history="${r.id}">View</button></div>`).join(''):'<div class="empty">Completed workouts will appear here.</div>'}</section>`;}
function nutrition(){const t=totals(),p=state.profile;return `<div class="page-heading"><div><span class="eyebrow">Nutrition journal</span><h2>Fuel your next session.</h2></div><button class="primary" data-action="meal">+ Add Food</button></div><div class="grid two"><div><section class="card nutrition-totals">${nutritionSummary()}</section><div class="stack">${['Breakfast','Lunch','Dinner','Snack'].map(label=>{const list=meals().filter(r=>r.value.meal===label);return `<section class="card"><div class="card-top"><h3>${label}</h3><span class="badge">${list.reduce((a,r)=>a+r.value.calories,0)} kcal</span></div>${list.length?list.map(r=>`<div class="food-row"><div class="food-name">${esc(r.value.name)}<small>${r.value.quantity} ${esc(r.value.serving)} · P ${r.value.protein}g / C ${r.value.carbs}g / F ${r.value.fat}g</small></div><span>${r.value.calories} kcal</span><button data-edit-meal="${r.id}">Edit</button><button class="quiet danger" data-delete="${r.id}">Delete</button></div>`).join(''):'<p class="subtle">No foods logged.</p>'}<button class="quiet" data-meal-type="${label}">+ Add to ${label}</button></section>`;}).join('')}</div></div><aside class="stack"><section class="card"><h3>Recent Foods</h3><p class="subtle">Log a previous food again with its recorded portions.</p>${records('meal').slice(0,5).map(r=>`<div class="history-item"><div class="item-copy"><strong>${esc(r.value.name)}</strong><small>${r.value.calories} kcal · ${r.value.quantity} ${esc(r.value.serving)}</small></div><button class="quiet" data-repeat="${r.id}" aria-label="Log ${esc(r.value.name)} again">+</button></div>`).join('')||'<p class="subtle">Your logged foods will appear here.</p>'}</section><section class="card"><h3>Your Daily Targets</h3>${[['Calories',p.calories+' kcal'],['Protein',p.protein+' g'],['Carbs',p.carbs+' g'],['Fat',p.fat+' g']].map(([l,v])=>`<div class="detail-line"><span>${l}</span><strong>${v}</strong></div>`).join('')}<button class="quiet wide" data-view="settings">Adjust Targets</button></section></aside></div>`;}
function coachView(){const hist=state.messages;return `<div class="page-heading"><div><span class="eyebrow">OpenGym Coach</span><h2>Understand your progress.</h2></div><span class="badge">${state.config.ai?'AI CONNECTED':'SETUP REQUIRED'}</span></div><div class="grid two"><section class="card"><div class="card-top"><h3>Your coaching conversation</h3><span class="badge">Based on your journal</span></div><div class="coach-feed" id="coach-feed">${hist.length?hist.map(m=>{if(m.role==='user')return `<div class="message user">${esc(m.text)}</div>`;let v;try{v=JSON.parse(m.text);}catch{v={answer:m.text};}return `<div class="message"><span class="sender">${icon('coach')} OPEN GYM COACH</span><p>${esc(v.answer)}</p>${v.observations?.length?`<strong>Observations</strong><ul>${v.observations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${v.suggestions?.length?`<strong>Suggested next steps</strong><ul>${v.suggestions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="limitations">${esc(v.limitations||'')}</p></div>`;}).join(''):'<div class="empty">'+icon('coach')+'<br>Ask about your training or nutrition.<br>Your coach uses the records you have actually logged.</div>'}</div>${!state.config.ai?'<div class="notice warning">AI coaching needs the server’s OpenAI configuration.</div>':''}<form id="coach-form"><div class="coach-form"><textarea name="prompt" maxlength="2000" required aria-label="Question for your coach" placeholder="How has my training changed this week?"></textarea><button class="primary" type="submit" ${!state.config.ai?'disabled':''}>Ask</button></div><p class="prototype-note">Illustrative coaching · no data is sent to an AI service</p><p class="subtle">Explore how a coaching conversation could feel.</p></form></section><aside class="stack"><section class="card"><h3>Training This Week</h3><div class="metric">${completedThisWeek()} <small>workouts</small></div>${volumeBars()}</section><section class="card"><h3>Recovery Context</h3>${records('recovery').slice(0,3).map(r=>`<div class="detail-line"><span>${r.value.date}</span><strong>${r.value.sleep}h sleep · ${r.value.energy}/5 energy</strong></div>`).join('')||'<p class="subtle">Log sleep and energy to add recovery context.</p>'}<button class="quiet wide" data-action="recovery">Add Check-in</button></section><section class="card"><h3>Nutrition Today</h3><div class="metric">${Math.round(totals().protein)} <small>g protein logged</small></div><p class="subtle">Target: ${state.profile.protein}g. Only logged foods are included.</p></section></aside></div>`;}
function volumeBars(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d.toISOString().slice(0,10);});const counts=days.map(d=>records('workout').filter(r=>r.value.date===d&&r.value.status==='completed').reduce((a,r)=>a+r.value.exercises.flatMap(e=>e.sets).filter(s=>s.done).length,0));return `<span class="eyebrow">Completed sets · last 7 days</span><div class="spark">${days.map((d,i)=>`<div class="spark-column"><progress value="${counts[i]}" max="${Math.max(10,...counts)}" aria-label="${d}: ${counts[i]} completed sets"></progress><small>${new Date(d+'T12:00:00').toLocaleDateString(undefined,{weekday:'narrow'})}</small></div>`).join('')}</div>`;}
const questOptions=[['Build a training rhythm','Complete 8 workouts over the next 30 days.',8],['A steady start','Complete 4 workouts over the next 30 days.',4],['Consistency season','Complete 12 workouts over the next 60 days.',12]];
function quests(){const list=records('quest');return `<div class="page-heading"><div><span class="eyebrow">Consistency compounds</span><h2>Seasons & Quests</h2></div></div><section class="card quest-feature"><span class="eyebrow">Your training, your pace</span><h2>Small steps. Lasting progress.</h2><p class="subtle">Build a rhythm around your life. Rest days are part of the plan, and there is no streak to lose.</p></section>${activityCalendar()}<div class="section-title"><h3>Your Quests</h3></div><div class="grid three">${list.length?list.map(r=>{const q=r.value,count=records('workout').filter(w=>w.value.status==='completed'&&w.value.date>=q.start&&w.value.date<=q.end).length,expired=q.end<date();return `<section class="card quest-card"><span class="badge ${count>=q.target?'good':''}">${count>=q.target?'COMPLETED':expired?'ENDED':'ACTIVE'}</span><h3>${esc(q.name)}</h3><div class="metric">${count}<small> / ${q.target} workouts</small></div><progress value="${count}" max="${q.target}" aria-label="Quest progress"></progress><p class="subtle">${q.start} through ${q.end}<br>Completed workouts count automatically.</p><button class="quiet" data-delete="${r.id}">Remove Quest</button></section>`;}).join(''):'<section class="card"><p class="subtle">Choose a quest below to get started.</p></section>'}</div><div class="section-title"><h3>Available Quests</h3></div><div class="grid three">${questOptions.map(([name,desc,target],i)=>`<section class="card quest-card"><span class="eyebrow">${target===12?'60':'30'}-day season</span><h3>${name}</h3><p class="subtle">${desc}</p><button class="primary" data-quest="${i}">Review Quest</button></section>`).join('')}</div>`;}
function settings(){const p=state.profile,g=state.integration;return `<div class="page-heading"><div><span class="eyebrow">Your account</span><h2>Make it yours.</h2></div><button class="quiet" data-action="prototype-logout">Sign Out</button></div><div class="settings-grid"><section class="card"><h3>Profile & Targets</h3><div class="integration-box"><strong>Your companion · ${cast[characterIndex].name}</strong><p>Choose the personality that feels right for your journey.</p><button class="quiet wide" data-action="avatar-studio">Change companion</button></div><form id="profile-form">${field('Display name','name',p.name)}<div class="field-grid"><label class="field">Weight unit<select name="unit"><option ${p.unit==='kg'?'selected':''}>kg</option><option ${p.unit==='lb'?'selected':''}>lb</option></select></label>${field('Daily calories','calories',p.calories,'number','min="500" max="10000"')}</div><div class="field-grid">${field('Protein (g)','protein',p.protein,'number')}${field('Carbs (g)','carbs',p.carbs,'number')}${field('Fat (g)','fat',p.fat,'number')}</div>${field('Training goal','goal',p.goal)}<p class="subtle">Changing units affects new workouts. Existing workouts keep their recorded units.</p><button class="primary" type="submit">Save Profile</button></form></section><section class="card"><h3>Preferences & Connections</h3><div class="integration-box"><div class="card-top"><strong>Appearance</strong><button class="quiet" type="button" data-action="theme" aria-label="Switch light and dark theme">${icon('moon')} Switch theme</button></div><p>Choose the appearance that feels right for you.</p></div><div class="integration-box accent-settings"><strong>Accent colour</strong><p>A soft splash of colour, in light or dark mode.</p><div class="accent-options" role="group" aria-label="Accent colour">${accentOptions.map(([key,name,colour])=>`<button type="button" class="accent-choice" data-action="accent" data-accent-choice="${key}" aria-pressed="${(localStorage.getItem('og-accent')||'peach')===key}"><span style="background:${colour}"></span>${name}</button>`).join('')}</div></div><div class="integration-box"><div class="card-top"><strong>Google Sheets</strong><span class="badge">${g?'CONNECTED':'NOT CONNECTED'}</span></div><p>Create a personal OpenGym spreadsheet and export your workout, nutrition, and recovery records. Sync updates the app-owned tabs; edits made in Sheets are not imported.</p>${sample?'<button class="quiet" data-action="prototype-sheets">Connect Google Sheets</button><p class="prototype-note">Preview the connection flow · no Google access requested</p>':g?`<div class="button-row"><button class="primary" data-action="sync">${g.sheet_id?'Sync Journal':'Create Sheet & Sync'}</button>${g.sheet_id?`<a href="https://docs.google.com/spreadsheets/d/${encodeURIComponent(g.sheet_id)}/edit" target="_blank" rel="noopener noreferrer">Open Sheet</a>`:''}</div><p class="subtle">Last sync: ${g.last_sync?new Date(g.last_sync).toLocaleString():'Not synced yet'}</p><button class="quiet danger" data-action="disconnect">Disconnect Sheets</button>`:'<a class="signin" href="/auth/google?mode=sheets">Connect Google Sheets</a>'}</div><div class="integration-box"><strong>AI Coach</strong><p>${state.config.ai?'Preview coaching uses illustrative responses.':'The server needs an OpenAI API key and model before coaching is available.'} You approve sharing your journal each time you ask a question.</p></div><div class="integration-box"><strong>Your Data</strong><p>Export a copy of your journal as JSON.</p><button class="quiet" data-action="export">Export Journal</button><button class="quiet" data-action="privacy">Privacy & Data</button></div></section></div>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${extra}></label>`;}
function modal(title,contents){const d=$('#modal');d.classList.remove('journal-calendar-dialog');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="quiet" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${contents}<p class="form-error" role="alert"></p>`;d.showModal();}
function closeModal(){$('#modal').close();}
function mealModal(record,type='Breakfast',repeat=false){const v=record?.value||{meal:type,name:$('#quick-note')?.value||'',quantity:1,serving:'serving',calories:0,protein:0,carbs:0,fat:0};modal(repeat?'Log Food Again':record?'Edit Food':'Add Food',`<form id="meal-form" data-record="${repeat?'':record?.id||''}"><label class="field">Meal<select name="meal">${['Breakfast','Lunch','Dinner','Snack'].map(x=>`<option ${v.meal===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Food name','name',v.name)}<div class="field-grid">${field('Quantity','quantity',v.quantity,'number','min="0.01" max="10000" step="0.01"')}${field('Serving unit','serving',v.serving)}</div><p class="subtle">Enter totals for this portion from a label or your own estimate.</p><div class="field-grid">${field('Calories (kcal)','calories',v.calories,'number','min="0" max="10000" step="0.1"')}${field('Protein (g)','protein',v.protein,'number','min="0" max="1000" step="0.1"')}${field('Carbs (g)','carbs',v.carbs,'number','min="0" max="1500" step="0.1"')}${field('Fat (g)','fat',v.fat,'number','min="0" max="1000" step="0.1"')}</div><div class="form-actions"><button type="button" data-action="close-modal">Cancel</button><button class="primary" type="submit">Save Food</button></div></form>`);}
function recoveryModal(){const r=recovery(),v=r?.value||{sleep:8,water:2,energy:3,notes:''};modal('Recovery Check-in',`<form id="recovery-form" data-record="${r?.id||''}"><div class="field-grid">${field('Sleep (hours)','sleep',v.sleep,'number','min="0" max="24" step="0.1"')}${field('Water (litres)','water',v.water,'number','min="0" max="20" step="0.1"')}</div><label class="field">Energy<select name="energy">${[1,2,3,4,5].map(x=>`<option value="${x}" ${x===v.energy?'selected':''}>${x} — ${['Very low','Low','Okay','Good','Excellent'][x-1]}</option>`).join('')}</select></label><label class="field">Notes (optional)<textarea name="notes" maxlength="1000">${esc(v.notes)}</textarea></label><div class="form-actions"><button type="button" data-action="close-modal">Cancel</button><button class="primary" type="submit">Save Check-in</button></div></form>`);}
const templates={'Push Session':['Barbell Bench Press','Incline Dumbbell Press','Standing Overhead Press','Cable Lateral Raise'],'Pull Session':['Lat Pulldown','Seated Cable Row','Dumbbell Curl'],'Leg Session':['Back Squat','Romanian Deadlift','Leg Press'],'Full Body':['Goblet Squat','Dumbbell Bench Press','Seated Cable Row']};
function startModal(){if(active()){view='workouts';location.hash=view;render();window.scrollTo(0,0);return;}modal('Start a Workout',`<form id="start-form">${field('Workout name','name','Push Session')}<label class="field">Template<select name="template">${Object.keys(templates).map(x=>`<option>${x}</option>`).join('')}</select></label><p class="subtle">Templates start with three sets per exercise. Enter your planned weight before logging.</p><div class="form-actions"><button type="button" data-action="close-modal">Cancel</button><button class="primary" type="submit">Start Workout</button></div></form>`);}
function exerciseModal(){modal('Add Exercise',`<form id="exercise-form">${field('Exercise name','name')}${field('Rest between sets (seconds)','rest',90,'number','min="0" max="900"')}<div class="form-actions"><button class="primary" type="submit">Add Exercise</button></div></form>`);}
function updateClock(){const remaining=restPause||Math.max(0,Math.ceil((restUntil-Date.now())/1000));const el=$('#rest-clock');if(el)el.textContent=remaining?`${Math.floor(remaining/60).toString().padStart(2,'0')}:${(remaining%60).toString().padStart(2,'0')}`:'Ready';const b=$('#pause-rest');if(b)b.textContent=restPause?'Resume':'Pause';}
setInterval(updateClock,1000);
function sampleJournal(){sample=true;const now=date();state={...state,user:null,profile:{name:'Alex Morgan',unit:'kg',calories:2500,protein:160,carbs:300,fat:70,goal:'Build strength consistently'},messages:[],integration:null,records:[{id:uuid(),kind:'workout',version:1,updated:Date.now(),value:{name:'Push Session A',date:now,status:'active',unit:'kg',startedAt:new Date().toISOString(),finishedAt:null,exercises:templates['Push Session'].map((name,i)=>({id:uuid(),name,rest:90,sets:Array.from({length:3},(_,j)=>({id:uuid(),weight:i===0?60:20,reps:8,rpe:j===0?8:null,done:i===0&&j===0}))}))}},...['Breakfast','Lunch'].map((meal,i)=>({id:uuid(),kind:'meal',version:1,updated:Date.now()-i*100,value:{date:now,meal,name:i?'Chicken, rice & vegetables':'Oats, banana & Greek yogurt',quantity:1,serving:'bowl',calories:i?680:520,protein:i?48:32,carbs:i?80:70,fat:i?16:12}})),{id:uuid(),kind:'recovery',version:1,updated:Date.now(),value:{date:now,sleep:7.5,water:2.1,energy:4,notes:''}}]};view='overview';render();}
document.addEventListener('change',e=>{const el=e.target;if(el.id==='journal-date'){selectedDate=el.value;render();}if(el.dataset.set){const a=active(),s=a?.value.exercises.flatMap(x=>x.sets).find(s=>s.id===el.dataset.set);if(s)s[el.dataset.field]=el.value===''&&el.dataset.field==='rpe'?null:Number(el.value);}});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.calendarDate){selectedDate=b.dataset.calendarDate;render();return;}if(b.dataset.view){view=b.dataset.view;location.hash=view;render();window.scrollTo(0,0);return;}if(b.dataset.exercise){currentExercise=Number(b.dataset.exercise);render();return;}const r=id=>state.records.find(x=>x.id===id);
 if(b.dataset.editMeal)return mealModal(r(b.dataset.editMeal));if(b.dataset.repeat)return mealModal(r(b.dataset.repeat),'Breakfast',true);if(b.dataset.mealType)return mealModal(null,b.dataset.mealType);
 if(b.dataset.delete)return run(()=>remove(r(b.dataset.delete)));
 if(b.dataset.complete)return run(async()=>{const a=active(),before=structuredClone(a.value),s=a.value.exercises[currentExercise].sets.find(x=>x.id===b.dataset.complete);if(!s.done&&(s.reps<1||s.weight<0))throw new Error('Enter reps and weight before completing the set.');s.done=!s.done;try{await save('workout',a.value,a);}catch(err){a.value=before;throw err;}if(s.done){restUntil=Date.now()+a.value.exercises[currentExercise].rest*1000;restPause=0;}render();toast(s.done?'Set saved. Rest timer started.':'Set reopened.');});
 if(b.dataset.quest){const q=questOptions[Number(b.dataset.quest)];const end=new Date();end.setDate(end.getDate()+(q[2]===12?60:30));modal('Review Quest',`<h3>${q[0]}</h3><p class="subtle">${q[1]} Completed workouts between ${date()} and ${end.toISOString().slice(0,10)} will count. Rest days do not reset progress.</p><button class="primary wide" data-join="${b.dataset.quest}">Join Quest</button>`);return;}
 if(b.dataset.join)return run(async()=>{const q=questOptions[Number(b.dataset.join)],end=new Date();end.setDate(end.getDate()+(q[2]===12?60:30));await save('quest',{name:q[0],target:q[2],start:date(),end:end.toISOString().slice(0,10)});closeModal();render();toast('Quest joined.');});
 if(b.dataset.history){const w=r(b.dataset.history).value;modal(esc(w.name),`<p class="subtle">${w.date} · ${w.unit}</p>${w.exercises.map(x=>`<h3>${esc(x.name)}</h3><p class="subtle">${x.sets.filter(s=>s.done).map(s=>`${s.weight} ${w.unit} × ${s.reps}${s.rpe?' · RPE '+s.rpe:''}`).join('<br>')||'No sets logged'}</p>`).join('')}`);return;}
 if(b.dataset.characterChoice!==undefined){selectCharacter(Number(b.dataset.characterChoice));return;}if(b.dataset.characterStep){selectCharacter(characterIndex+Number(b.dataset.characterStep));return;}const action=b.dataset.action||(b.dataset.persona?'persona':b.dataset.avatar?'avatar':'');if(!action)return;e.preventDefault();
 if(b.dataset.accentChoice){localStorage.setItem('og-accent',b.dataset.accentChoice);applyAccent();document.querySelectorAll('[data-accent-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return;}if(action==='companion-flip'){const flipped=b.classList.toggle('is-flipped');b.setAttribute('aria-expanded',String(flipped));b.setAttribute('aria-label',flipped?'Return to '+cast[characterIndex].name:'Learn about '+cast[characterIndex].name);b.querySelector('.companion-front').setAttribute('aria-hidden',String(flipped));b.querySelector('.companion-back').setAttribute('aria-hidden',String(!flipped));return;}if(action==='prototype-sheets'){modal('Connect Google Sheets','<p class="subtle">Your journal, in your own spreadsheet.</p><p class="prototype-note">This is a connection preview. No spreadsheet is created.</p><button class="primary wide" data-action="prototype-sheets-done">Allow connection</button>');return;}if(action==='prototype-sheets-done'){closeModal();toast('Connection preview complete.');return;}if(action==='google-preview'||action==='switch-user'){modal('Choose your account',`<p class="subtle">Continue to OpenGym with a preview persona.</p><div class="persona-list">${[['alex','Alex Morgan','alex@example.com'],['maya','Maya Chen','maya@example.com'],['sam','Sam Rivera','sam@example.com']].map(([id,name,email])=>`<button data-persona="${id}"><span class="persona-avatar">${avatarArt(id)}</span><span>${name}<small>${email}</small></span>${icon('arrow')}</button>`).join('')}</div><p class="prototype-note">Prototype account chooser · no credentials or Google connection required</p>`);return;}if(b.dataset.persona){signInPreview(b.dataset.persona);return;}if(action==='prototype-logout'){sample=false;state.user=null;view='landing';location.hash='landing';render();return;}if(action==='choose-character'){localStorage.setItem('og-companion-'+state.user.id,characterIndex);document.querySelector('.cast-stage')?.classList.add('celebrating');setTimeout(()=>{view='overview';location.hash=view;render();window.scrollTo(0,0);toast(cast[characterIndex].name+' is joining your journey.');},matchMedia('(prefers-reduced-motion: reduce)').matches?0:650);return;}if(action==='avatar-studio'){view='character';location.hash=view;render();window.scrollTo(0,0);return;}if(action==='unused-avatar-studio'){modal('Make it feel like you',`<p class="subtle">Choose your companion’s look.</p><div class="avatar-options">${[0,1,2].map(i=>`<button data-avatar="${i}">${avatarArt(state.user.id,i)}<span>Look ${i+1}</span></button>`).join('')}</div><p class="prototype-note">Appearance is saved on this device for this persona.</p>`);return;}if(b.dataset.avatar){localStorage.setItem('og-avatar-'+state.user.id,b.dataset.avatar);closeModal();render();return;}if(action==='close-modal')return closeModal();if(action==='sample')return sampleJournal();if(action==='exit-sample'){sample=false;load();return;}if(action==='theme'){localStorage.setItem('og-theme',document.body.classList.contains('light')?'dark':'light');document.body.classList.toggle('light');return;}if(action==='start')return startModal();if(action==='meal')return mealModal();if(action==='recovery')return recoveryModal();if(action==='add-exercise')return exerciseModal();
 if(action==='quick-log')return modal('Choose an Entry',`<p class="subtle">${esc($('#quick-note').value||'What would you like to record?')}</p><div class="button-row"><button class="primary" data-action="meal">Food</button><button data-action="start">Workout</button><button data-action="recovery">Recovery</button></div>`);
 if(action==='pause-rest'){if(restPause){restUntil=Date.now()+restPause*1000;restPause=0;}else{restPause=Math.max(0,Math.ceil((restUntil-Date.now())/1000));restUntil=0;}updateClock();return;}if(action==='extend-rest'){if(restPause)restPause+=30;else restUntil=Math.max(Date.now(),restUntil)+30000;updateClock();return;}if(action==='skip-rest'){restUntil=0;restPause=0;updateClock();return;}
 if(action==='add-set')return run(async()=>{const a=active(),v=structuredClone(a.value),sets=v.exercises[currentExercise].sets;if(sets.length>=30)throw new Error('Maximum 30 sets per exercise.');sets.push({...sets.at(-1),id:uuid(),done:false,rpe:null});await save('workout',v,a);render();});
 if(action==='save-workout')return run(async()=>{const a=active();await save('workout',a.value,a);toast('Workout changes saved.');render();});
 if(action==='finish'){const a=active(),sets=a.value.exercises.flatMap(e=>e.sets);modal('Finish Workout',`<p class="subtle">${sets.filter(s=>s.done).length} of ${sets.length} sets completed. ${sets.some(s=>!s.done)?'Incomplete sets will remain unlogged.':''}</p><div class="form-actions"><button data-action="close-modal">Keep Training</button><button class="primary" data-action="confirm-finish">Save Workout</button></div>`);return;}
 if(action==='confirm-finish')return run(async()=>{const a=active();if(!a.value.exercises.some(e=>e.sets.some(s=>s.done)))throw new Error('Log at least one set before finishing.');await save('workout',{...a.value,status:'completed',finishedAt:new Date().toISOString()},a);closeModal();restUntil=0;restPause=0;render();toast('Workout completed.');});
 if(action==='plates'){const total=Number($('#plate-total').value),bar=Number($('#plate-bar').value);if(total<bar){$('#plate-result').textContent='Total weight must include the bar.';return;}const plates=active().value.unit==='kg'?[25,20,15,10,5,2.5,1.25]:[45,35,25,10,5,2.5];let remain=(total-bar)/2,out=[];for(const p of plates){const count=Math.floor((remain+0.001)/p);if(count){out.push(`${count} × ${p}`);remain-=count*p;}}$('#plate-result').textContent=`Per side: ${out.join(' + ')||'Bar only'}${remain>0.01?` · ${remain.toFixed(2)} unmatched per side`:''}`;return;}
 if(action==='sync')return run(async()=>{toast('Syncing your journal…');await api('/api/sheets/sync','POST',{});await load();toast('Journal synced to Google Sheets.');});
 if(action==='disconnect')return run(async()=>{await api('/api/sheets/disconnect','POST',{});await load();toast('Sheets disconnected. Your spreadsheet is retained.');});
 if(action==='logout')return run(async()=>{await api('/api/logout','POST',{});await load();});
 if(action==='export')return run(async()=>{const data=sample?{profile:state.profile,records:state.records}:await api('/api/export');const href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download='opengym-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);});
 if(action==='privacy')return modal('About this prototype','<p class="subtle">OpenGym is an interactive design mockup. Sign-in, coaching, and integrations are simulated. No account is created and no journal data is sent to external services.</p><p class="subtle">Avatar preferences are stored locally on this device. Journal interactions reset when the preview is refreshed or the persona changes.</p>');
});
document.addEventListener('submit',e=>{const f=e.target;if(!['meal-form','start-form','recovery-form','exercise-form','profile-form','coach-form'].includes(f.id))return;e.preventDefault();run(async()=>{const v=Object.fromEntries(new FormData(f)),r=state.records.find(r=>r.id===f.dataset.record);if(f.id==='meal-form'){for(const k of ['quantity','calories','protein','carbs','fat'])v[k]=Number(v[k]);await save('meal',{...v,date:selectedDate},r);}if(f.id==='recovery-form'){for(const k of ['sleep','water','energy'])v[k]=Number(v[k]);await save('recovery',{...v,date:selectedDate},r);}if(f.id==='start-form'){const exercises=templates[v.template].map(name=>({id:uuid(),name,rest:90,sets:Array.from({length:3},()=>({id:uuid(),weight:0,reps:8,rpe:null,done:false}))}));await save('workout',{name:v.name,date:date(),status:'active',unit:state.profile.unit,startedAt:new Date().toISOString(),finishedAt:null,exercises});view='workouts';location.hash=view;currentExercise=0;}if(f.id==='exercise-form'){const a=active(),value=structuredClone(a.value);value.exercises.push({id:uuid(),name:v.name,rest:Number(v.rest),sets:Array.from({length:3},()=>({id:uuid(),weight:0,reps:8,rpe:null,done:false}))});await save('workout',value,a);currentExercise=value.exercises.length-1;}if(f.id==='profile-form'){for(const k of ['calories','protein','carbs','fat'])v[k]=Number(v[k]);state.profile=sample?v:await api('/api/profile','PUT',v);}if(f.id==='coach-form'){toast('Your coach is reviewing your journal…');const response=await api('/api/coach','POST',{prompt:v.prompt,consent:v.consent==='on'});state.messages.push({role:'user',text:v.prompt},{role:'assistant',text:JSON.stringify(response)});render();$('#coach-feed').scrollTop=$('#coach-feed').scrollHeight;toast('Coach response ready.');return;}if($('#modal').open)closeModal();render();toast('Saved.');});});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(view===next)return;view=next;render();});
load().then(()=>{const error=new URLSearchParams(location.search).get('error');if(error)toast(error);}).catch(e=>{$('#app').innerHTML='<div class="loading">Could not load your journal. Refresh to try again.</div>';toast(e.message);});

document.addEventListener('keydown',e=>{if(view==='character'&&!e.target.matches('input,textarea,select')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();selectCharacter(characterIndex+(e.key==='ArrowRight'?1:-1));}});


let calendarMonth;
const calendarKey=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
function openJournalCalendar(){calendarMonth=new Date(selectedDate+'T12:00:00');calendarMonth.setDate(1);modal('Your journal, by day','');$('#modal').classList.add('journal-calendar-dialog');paintJournalCalendar();}
function paintJournalCalendar(focusKey){
 const d=$('#modal'),start=new Date(calendarMonth);start.setDate(1-start.getDay());
 const logged=new Set(state.records.filter(r=>['workout','meal','recovery'].includes(r.kind)).map(r=>r.value.date));
 const days=Array.from({length:42},(_,i)=>{const day=new Date(start);day.setDate(start.getDate()+i);const key=calendarKey(day),chosen=key===selectedDate;return '<button type="button" role="gridcell" data-journal-day="'+key+'" class="journal-day '+(day.getMonth()!==calendarMonth.getMonth()?'outside-month ':'')+(chosen?'selected ':'')+(key===date()?'is-today ':'')+(logged.has(key)?'has-entry':'')+'" aria-selected="'+chosen+'" '+(key===date()?'aria-current="date" ':'')+'aria-label="'+esc(pretty(key))+(logged.has(key)?', journal entries':'')+'">'+day.getDate()+'</button>';});
 d.innerHTML='<div class="modal-head"><span class="eyebrow">YOUR JOURNAL, BY DAY</span><button type="button" class="quiet" data-action="close-modal" aria-label="Close calendar">'+icon('close')+'</button></div><div class="journal-month-heading"><button type="button" class="quiet" data-journal-month="-1" aria-label="Previous month">‹</button><h2 id="journal-month-label">'+calendarMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'})+'</h2><button type="button" class="quiet" data-journal-month="1" aria-label="Next month">›</button></div><div class="journal-weekdays" aria-hidden="true">'+['S','M','T','W','T','F','S'].map(x=>'<span>'+x+'</span>').join('')+'</div><div class="journal-day-grid" role="grid" aria-labelledby="journal-month-label">'+days.map((x,i)=>i%7===0?'<div role="row">'+days.slice(i,i+7).join('')+'</div>':'').join('')+'</div><div class="journal-calendar-footer"><span><i></i> Journal entry</span><button type="button" class="quiet" data-journal-day="'+date()+'">Back to today</button></div>';
 d.querySelector('[data-journal-day="'+(focusKey||selectedDate)+'"]')?.focus();
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.datePicker){e.stopImmediatePropagation();openJournalCalendar();}else if(b.dataset.journalMonth){e.stopImmediatePropagation();calendarMonth.setMonth(calendarMonth.getMonth()+Number(b.dataset.journalMonth));paintJournalCalendar();$('#modal [data-journal-month="'+b.dataset.journalMonth+'"]').focus();}else if(b.dataset.journalDay){e.stopImmediatePropagation();selectedDate=b.dataset.journalDay;closeModal();render();$('#journal-date')?.focus();}},true);
document.addEventListener('keydown',e=>{const key=e.target.dataset?.journalDay;if(!key||!$('#modal').open)return;const offsets={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7};if(!(e.key in offsets))return;e.preventDefault();const next=new Date(key+'T12:00:00');next.setDate(next.getDate()+offsets[e.key]);if(next.getMonth()!==calendarMonth.getMonth()||next.getFullYear()!==calendarMonth.getFullYear()){calendarMonth=new Date(next);calendarMonth.setDate(1);paintJournalCalendar(calendarKey(next));}else $('#modal [data-journal-day="'+calendarKey(next)+'"]')?.focus();});

